const selectedId = variables['8534c123-e25d-4475-b48a-19afb9dbbb81'];
const lead = (globalContext.tableViews['5fc4b493-1e9e-4de8-8102-668c1e8a00aa']?.data || []).find(row => row.id === selectedId);
const normalizedStatus = String(lead?.lead_status || 'New Lead').toLowerCase();
const isLost = normalizedStatus.includes('lost');
let currentIndex = 0;
if (normalizedStatus.includes('contact')) currentIndex = 1;
if (normalizedStatus.includes('qualif') || normalizedStatus.includes('appointment')) currentIndex = 2;
if (normalizedStatus.includes('offer')) currentIndex = 3;
if (normalizedStatus.includes('contract')) currentIndex = 5;
if (normalizedStatus.includes('dispo')) currentIndex = 8;
if (normalizedStatus.includes('closed')) currentIndex = 11;
const overrides = (globalContext.tableViews['7a5110e6-060d-442b-80f9-19843cd8b197']?.data || []).filter(row => row.deal_id === selectedId && row.stage_key === 'buyer_selected').sort((a, b) => String(a.updatedAt || '').localeCompare(String(b.updatedAt || '')));
const override = overrides[overrides.length - 1]?.stage_state;
const status = override || (isLost ? (9 === 0 ? 'blocked' : 'pending') : (9 < currentIndex ? 'completed' : (9 === currentIndex ? 'current' : 'pending')));
return status === 'completed' ? '#166534' : (status === 'current' ? '#15803D' : (status === 'attention' ? '#B45309' : (status === 'blocked' ? '#991B1B' : '#1E293B')));

