const raw = globalContext.tableViews['5fc4b493-1e9e-4de8-8102-668c1e8a00aa']?.data || [];
const search = (variables['cfb8586f-e546-48be-bd2d-4efdb483f792'] || '').toLowerCase().trim();
const stage = variables['5a5b92b5-a0ea-48f9-98db-e78f95b3a7ec'] || 'All';
const source = variables['8f619894-1cc7-4de1-a441-352f5af2d12a'] || 'All';
const zip = variables['8c14ab11-a4e8-4be6-94d5-a562d3c27a03'] || 'All';
const assigned = variables['a5def06a-a49b-4478-afd7-7359cd317fe2'] || 'All';
const minScore = Number(variables['63b4f120-aa27-4905-b035-79da169cdf7f']) || 0;

return raw.filter(item => {
  if (!item) return false;
  if (search) {
    const matchAddr = (item.property_address || '').toLowerCase().includes(search);
    const matchSeller = (item.seller_name || '').toLowerCase().includes(search);
    const matchPhone = (item.phone || '').toLowerCase().includes(search);
    const matchZip = (item.zip_code || '').toLowerCase().includes(search);
    if (!matchAddr && !matchSeller && !matchPhone && !matchZip) return false;
  }
  if (stage !== 'All' && item.lead_status !== stage) return false;
  if (source !== 'All' && item.source !== source) return false;
  if (zip !== 'All' && item.zip_code !== zip) return false;
  if (assigned !== 'All' && item.assigned_to !== assigned) return false;
  if (minScore > 0 && (Number(item.lead_score) || 0) < minScore) return false;
  return true;
});

